function deepMerge(target, source) {
  if (!target || !source) return target ?? {};
  const isPlainObject = obj =>
    typeof obj === 'object' &&
    obj !== null &&
    !Array.isArray(obj);

  function safeSet(targetObj, key, value) {
    if (key in ['__proto__', 'constructor', 'prototype']) return;
    Object.defineProperty(targetObj, key, {
      value: value,
      writable: true,
      enumerable: true,
      configurable: true,
    });
  }

  function clone(obj) {
    if (!isPlainObject(obj)) return obj;
    const copy = {};
    for (const k in obj) {
      safeSet(copy, k, obj[k]);
    }
    return copy;
  }

  const result = clone(target);

  for (const key in source) {
    if (!Object.prototype.hasOwnProperty.call(source, key)) continue;
    const srcVal = source[key];
    const tgtVal = result[key];

    if (isPlainObject(srcVal) && isPlainObject(tgtVal)) {
      deepMerge(tgtVal, srcVal);
    } else {
      safeSet(result, key, clone(srcVal));
    }
  }

  return result;
}

function splitFees(totalWei, sharesBps) {
  if (typeof totalWei !== "bigint") throw new Error("totalWei must be a BigInt");
  if (!Array.isArray(sharesBps)) throw new Error("sharesBps must be an array");

  const totalShares = sharesBps.reduce((sum, val) => sum + Number(val), 0);
  if (totalShares !== 10000) throw new Error("sharesBps must sum to exactly 10000");

  let remainder = BigInt(0);
  const payouts = [];

  for (let i = 0; i < sharesBps.length; i++) {
    const shareBps = Number(sharesBps[i]);
    if (!Number.isInteger(shareBps)) throw new Error("Each share must be an integer basis point");

    let payout = totalWei * BigInt(shareBps) / 10000n;
    payouts.push(payout);
    remainder += (totalWei - payouts.reduce((sum, p) => sum + p, 0n));
  }

  if (remainder > 0n) {
    payouts[payouts.length - 1] = payouts[payouts.length - 1] + remainder;
  }

  return payouts;
}

function parseUnits(amountStr, decimals) {
  if (typeof amountStr !== 'string') throw new TypeError('amountStr must be a string');
  const trimmed = amountStr.trim();
  if (!trimmed) throw new Error('Empty input');

  let integerPart = '';
  let fractionalPart = '';
  let dotIndex = trimmed.indexOf('.');

  if (dotIndex === -1) {
    integerPart = trimmed;
  } else {
    integerPart = trimmed.slice(0, dotIndex);
    fractionalPart = trimmed.slice(dotIndex + 1);
  }

  if (!integerPart && !fractionalPart) throw new Error('No digits found');

  const intVal = BigInt(integerPart || '0');
  let fracVal = BigInt(fractionalPart || '0');

  if (fracVal > 0n && fractionalPart.length > decimals) {
    throw new Error(`Fractional part exceeds ${decimals} decimal places`);
  }

  const multiplier = 10n ** BigInt(decimals);
  return intVal * multiplier + fracVal;
}

function formatUnits(amountBig, decimals) {
  if (!(amountBig instanceof BigInt)) throw new TypeError('amountBig must be a BigInt');
  if (typeof decimals !== 'number' || !Number.isInteger(decimals) || decimals < 0) {
    throw new TypeError('decimals must be a non-negative integer');
  }

  const multiplier = 10n ** BigInt(decimals);
  let quotient, remainder;

  if (amountBig >= 0n) {
    [quotient, remainder] = amountBig.divMod(multiplier);
  } else {
    // Handle negative numbers correctly with divMod
    const negAmount = -amountBig;
    [quotient, remainder] = negAmount.divMod(multiplier);
    quotient = -quotient;
    if (remainder > 0n) quotient -= 1n;
  }

  let fracStr = '';
  if (remainder !== 0n) {
    const remainderStr = remainder.toString().padStart(decimals, '0');
    fracStr = '.' + remainderStr.slice(-decimals);
  }

  let result = quotient.toString() + fracStr;

  // Trim trailing zeros in the fraction and handle edge cases
  if (fracStr) {
    const dotIndex = result.indexOf('.');
    const fractionDigits = result.slice(dotIndex + 1);

    // Find last non-zero digit from right to left
    let lastNonZeroIdx = -1;
    for (let i = fractionDigits.length - 1; i >= 0; i--) {
      if (fractionDigits[i] !== '0') {
        lastNonZeroIdx = i;
        break;
      }
    }

    if (lastNonZeroIdx === -1) {
      // All zeros in fraction -> strip decimal point entirely
      result = quotient.toString();
    } else {
      const trimIndex = dotIndex + 1 + lastNonZeroIdx + 1;
      result = result.slice(0, trimIndex);
    }
  }

  return result;
}

function checkTransferResult(returnData, didRevert) {
  if (didRevert === true) {
    return false;
  }

  const isEmpty = returnData == null || returnData === "0x";
  if (isEmpty) {
    return true;
  }

  try {
    // Decode the last 32 bytes as a boolean: ...01 -> true, ...00 -> false
    const isTrue = Boolean(parseInt(returnData.slice(-64), 16) & 1);
    if (returnData.endsWith("01")) return true;
    if (returnData.endsWith("00")) return false;

    // If we reach here, the data doesn't cleanly match expected patterns.
    throw new Error(`Unexpected transfer result: ${returnData}`);
  } catch (e) {
    throw e;
  }
}
